import{af as t,z as a,J as o,ab as s}from"./chunks/framework.ss42i_gG.js";const p=JSON.parse('{"title":"How to set up the schedule feature","description":"","frontmatter":{"aside":false,"sidebar":false,"editLink":false},"headers":[],"relativePath":"guides/schedule-feature.md","filePath":"guides/schedule-feature.md"}'),i={name:"guides/schedule-feature.md"};function r(d,e,l,c,n,h){return a(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793282371000"},[...e[0]||(e[0]=[s('<h1 id="how-to-set-up-the-schedule-feature" tabindex="-1">How to set up the schedule feature <a class="header-anchor" href="#how-to-set-up-the-schedule-feature" aria-label="Permalink to &quot;How to set up the schedule feature&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">ℹ️ Information</p><p>Please note that this is an advanced feature, so if you require any support, please <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">get in touch</a>.</p></div><h2 id="schedule-feature" tabindex="-1">Schedule Feature <a class="header-anchor" href="#schedule-feature" aria-label="Permalink to &quot;Schedule Feature&quot;">​</a></h2><ol><li>Open the <a href="https://lightbug.cloud/" target="_blank" rel="noreferrer">Lightbug Web Portal</a></li><li>Go to <code>&#39;Settings&#39;</code>, then to the <code>&#39;Schedule&#39;</code> page<br><img src="https://upload.r2.lb.chasm.cloud/2026/10/docs-guides-fresh-grab/2043310948567-NA9Ortkw7wXdHjcPFr2cST2n21HoM-DnDQ.png" alt="" width="250"><img src="https://upload.r2.lb.chasm.cloud/2026/10/docs-guides-fresh-grab/2043310948434-sID8eiY38jHiSjU857Yq294Xp4pwb3bkeg.png" alt="" width="250"></li><li>Click on <code>&#39;ADD RULE&#39;</code><br><img src="https://upload.r2.lb.chasm.cloud/2026/10/docs-guides-fresh-grab/2043310979134-MTGn0eiUE_7Iyw1eIJerE4F4h-jx4CXhOw.png" alt="" width="250"></li><li>Enter the <code>day, time and frequency</code> that the action will take place<br><img src="https://upload.r2.lb.chasm.cloud/2026/10/docs-guides-fresh-grab/2043310981340-reea4MlxIREjYv45qYQJyoHf5Q8M2tTklA.png" alt="" width="250"></li><li>Select an <code>action</code>. Your tracker will perform this action on the selected time<br><img src="https://upload.r2.lb.chasm.cloud/2026/10/docs-guides-fresh-grab/2043310982235-u9f41BcfOHK-4SIZZT-r6dIDd3zv_Vgfxg.png" alt="" width="250"></li><li>Add the <code>rule</code>, and create additional rules if required. When finished, <code>save</code><br><img src="https://upload.r2.lb.chasm.cloud/2026/10/docs-guides-fresh-grab/2043311001014-XI8h_qSfQiVfgZSKXgpqB_mVvCxsACCOzA.png" alt="" width="250"></li></ol><p><strong><code>No Action:</code></strong> The tracker will do nothing. This action is here as a placeholder if you want to disable rules without deleting them.</p><p><strong><code>Sleep:</code></strong> This will lock the tracker in sleep mode. This means that it will transmit only on beacon interval. You can find and adjust the beacon interval on the <code>Configuration</code> page.</p><p><strong><code>Wake:</code></strong> This will lock the tracker in <code>wake mode</code>. This means that it will transmit on interval. This action is not suited for most use cases as it can drain the battery faster.</p><p><strong><code>Transmit:</code></strong> The tracker will send <code>one update</code> at the specified <code>time</code>. This action does <em>not</em> affect any of your tracker&#39;s update rate settings.</p><div class="tip custom-block"><p class="custom-block-title">⚡ Tip</p><p>Rules are evaluated in order.</p></div><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p><strong><code>Wednesday 8am Wake, Wednesday 4pm Sleep</code></strong> On Wednesday you will receive frequent updates between 8am-4pm. The rest of the time you will receive sleep updates.</p><p><strong><code>All days 9am Transmit now</code></strong> You will receive a location update at <code>9am everyday</code>. This is in <em>addition</em> to any location updates sent due to your trackers settings.</p><h2 id="a-few-things-to-note" tabindex="-1">A Few Things To Note <a class="header-anchor" href="#a-few-things-to-note" aria-label="Permalink to &quot;A Few Things To Note&quot;">​</a></h2><p>Settings are automatically saved and will be applied at the next location update. Alternatively, to apply the new settings immediately, press the button on your tracker for 3 seconds These rules will override motion detection and geofence.</p><p>This feature can be a little complicated to set up, so if you have any hesitations, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">please reach out to us</a>.</p>',15)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
